import mapboxgl from 'mapbox-gl';
import { RendererWrapper } from '../';

import { downloadImage } from '../../lib';

export class MapboxGLWrapper {
    public rendererWrapper: RendererWrapper;
    public map: mapboxgl.Map;
    public canvasMapbox;
    private isPressed: boolean = false;
    constructor(rendererWrapper: RendererWrapper) {
        this.rendererWrapper = rendererWrapper;

        this.initMap(rendererWrapper.solution.divHost.id);
    }
    private initMap(id: string) {
        // https://account.mapbox.com
        // mapboxgl.accessToken = import.meta.env.VITE_MAPBOX
        mapboxgl.accessToken = import.meta.env.VITE_MAPBOX;
        this.map = new mapboxgl.Map({
            preserveDrawingBuffer: true,
            container: id,
            zoom: 3,
            // pitch: 30,
            // minZoom: 10,
            // center: [-74.5, 40],
            center: [-77.430815, 37.801833],
            doubleClickZoom: false,
            style: 'mapbox://styles/mapbox/dark-v10' // 'mapbox://styles/mapbox/streets-v11'

        });
        this.map.doubleClickZoom.disable();
        this.map.dragRotate.disable();

        this.map.on('moveend', () => { this.rendererWrapper.solution.common.onExtentDone(); });
        this.map.on('zoom', () => { this.rendererWrapper.solution.common.renderForce(); });
        this.map.on('click', 'polygon', (e: any) => { this.rendererWrapper.solution.common.pickObject(e) });

        // https://docs.mapbox.com/mapbox-gl-js/api/events/#mapmouseevent#type
        this.map.on('mousemove', (e: mapboxgl.MapMouseEvent) => {
            if (this.isPressed) {
                this.mouseDrag(e);
            } else {
                this.mouseMove(e);
            }
        });
        this.map.on('click', (e: mapboxgl.MapMouseEvent) => { this.mouseClick(e); });
        this.map.on('mousedown', (e: mapboxgl.MapMouseEvent) => { this.isPressed = true; this.mouseDown(e); });
        this.map.on('dblclick', (e: mapboxgl.MapMouseEvent) => { this.mouseDClick(e); });
        this.map.on('mouseup', (e: mapboxgl.MapMouseEvent) => { this.isPressed = false; this.mouseUp(e); });
        window.addEventListener('keydown', (k) => { this.keyDown(k) });

        let div = document.getElementsByClassName('mapboxgl-canvas')[0] as HTMLDivElement;
        div.style.position = 'absolute';

        div = document.getElementsByClassName('mapboxgl-control-container')[0] as HTMLDivElement;
        div.style.display = 'none';

        this.map.on('load', () => { this.initPost(); });
    }
    public initPost() {
        this.rendererWrapper.initPost();
        this.canvasMapbox = this.map.getCanvas();

        // this.initCustomCanvas();
    }

    public initCustomCanvas() {
        // console.log('initCustomCanvas');
        this.rendererWrapper.renderer.canvas.width = this.canvasMapbox.width;
        this.rendererWrapper.renderer.canvas.height = this.canvasMapbox.height;

        this.rendererWrapper.renderer.canvas.style.display = 'none';

        const bound: any = this.map.getBounds();
        // console.log(bound);

        this.map.on('load',  () => {
            this.map.addSource('canvas-source', {
                type: 'raster',
                canvas: this.rendererWrapper.renderer.canvas,
                coordinates: [

                    // [ 180, 90],
                    // [ 180, -90],
                    // [ -180, -90], 
                    // [ -180, 90]


                    // [bound._sw[0], bound._sw[1]],
                    // [bound._sw[0], bound._ne[1]],
                    // [bound._ne[0], bound._ne[1]],
                    // [bound._ne[0], bound._sw[1]],

                    [-125.618336, 48.944262],
                    [-125.618336, 24.786775],
                    [-65.591812, 24.786775],
                    [-65.591812, 48.944262]

                    // [91.4461, 21.5006],
                    // [100.3541, 21.5006],
                    // [100.3541, 13.9706],
                    // [91.4461, 13.9706]
                ],
                // Set to true if the canvas source is animated. If the canvas is static, animate should be set to false to improve performance.
                animate: true
            });

            this.map.addLayer({
                id: 'canvas-layer',
                type: 'raster',
                source: 'canvas-source'
            });
        })

    }
    public zoom = (z: number) => {
        // this.map.setZoom(z);
        // return this.map.zoomTo(z, {animate:true} )
        return this.map.zoomTo(z)
    }
    public flyTo = (lng: number, lat: number) => {
        return this.map.flyTo({
            center: [lng, lat],
            // duration: 1200, // Animate over 12 seconds
            // essential: true
        });
    }
    public center = (lng: number = -99.292649, lat: number = 39.043903) => {
        // const v = new mapboxgl.LngLat(lng, lat);
        // console.log(v);
        return this.map.setCenter({ lat, lng })
    }
    public toMap = (x: number, y: number) => {
        const p = this.map.unproject({ x, y } as any)
        return [p.lng, p.lat];
    }
    public toScreen = (lon: number, lat: number) => {
        try {
            const p = this.map.project([lon, lat])
            return [p.x, p.y];
        } catch (error) {
            // console.error(error)
        }
        return [-1, -1];
    }
    public downloadImage() {
        const canvasMapbox = this.map.getCanvas();
        return downloadImage(canvasMapbox, this.rendererWrapper.renderer.canvas);
    }
    public getViewState() {
        const center = this.map.getCenter();
        // console.log(center);
        return {
            zoom: this.map.getZoom(),
            center: center,
        };
    }
    public mouseDown = (e) => { }
    public mouseUp = (e) => { }
    public mouseMove = (e) => { }
    public mouseDrag = (e) => { }
    public mouseClick = (e) => { }
    public mouseDClick = (e) => { }
    public keyDown = (e) => { }
}
