import { RVector3 } from './';
export const drawingPoint = (ctx: CanvasRenderingContext2D, x: number, y: number) => {
    ctx.beginPath();
    ctx.arc(x, y, 10, 0, Math.PI * 2.0);
    ctx.closePath();
    ctx.fill();
};
export const renderControlPoint = (ctx: CanvasRenderingContext2D, vs: RVector3[], fillColor = 'rgba(200, 200, 200, 1.0)', strokeColor = 'rgba(50, 50, 50, 1.0)', lineWidth = 3 ) => {
    ctx.fillStyle = fillColor;
    ctx.strokeStyle = strokeColor;
    ctx.lineWidth = lineWidth;
    vs.forEach(v => {
        ctx.beginPath();
        ctx.arc(v.x, v.y, 8, 0, Math.PI * 2.0);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();
        // console.log(v.x, v.y)
    });
};