import * as turf from '@turf/turf';

import { Solution } from '../';
import { SceneState } from './SceneState';
import { ACCommon } from '../Common';
import { ActiveCommander } from '../ActiveCommander';
import { GeometryBase } from '../Geometry/GeometryCanvas/Base/GeometryBase';
import { hex2RGB, drawingPoint } from '../lib';

import { LANDUSE_TYPE_MAPPING, FUNDING_STATUS_MAPPING } from '../lib/constant';

export class Scene {
    public solution: Solution;
    public ac: ActiveCommander;
    public stateManager: SceneState;
    public common: ACCommon;

    public pts: number[] = [];

    public areas: GeometryBase[] = [];
    public captured: GeometryBase | undefined = undefined;

    public points: any;
    public polygonsDifference: any = [];
    public ids: boolean[] =[];

    constructor(solution: Solution) {
        this.solution = solution;
        this.stateManager =  new SceneState(this);
        this.ac = solution.activeCommander;
        this.common = solution.common;
    }
    public initPre() {
        this.stateManager.captureState();
    }
    public push(g: GeometryBase) {
        this.areas.push(g);
    }
    public remove(g: GeometryBase) {
        this.areas.splice(this.areas.indexOf(g), 1);
    }
    public async init() {
        this.common.center(-112.190375, 35.257177);
        this.common.zoom(13);


        // init starting

        const polygons = await this.common.loadDataLocal('funded_census_blocks.geojson');
        const gons = [];
        const ids = [];
        const colDefault = hex2RGB(FUNDING_STATUS_MAPPING.default.color);
        const colAssigned = hex2RGB(FUNDING_STATUS_MAPPING.assigned.color);
        // console.log(polygons);
        for (let i of polygons['features']) {
            const p = (i['geometry']['coordinates']);
            let color = undefined;
            const grantStatus = (i['properties']['grant_long_status']);
            // console.log(grantStatus)
            if (grantStatus === 'default') { color = colDefault; }
            else { color = colAssigned; }
            // if (Math.random() < 0.3) { color = ColorUtility.GetRandomRGBArray(); }
            // console.log(color)
            gons.push({ contour: p[0], size: 15, color: color });
            ids.push(false);
        }
        // console.log(gons)
        this.ids = ids;
        const onClickEvent = (info, event) => {
            // console.log('!', info)
            // console.log('!', info.index)
            this.ids[info.index] = !this.ids[info.index];
            this.common.renderForce();
        }
        this.common.addPolygonLayer(gons, onClickEvent);


        const polygonsDiff = await this.common.loadDataLocal('funded_census_blocks.geojson');
        this.polygonsDifference = []
        for (let i of polygonsDiff['features']) {
            const p = (i['geometry']['coordinates']);
            // console.log(p[0])
            this.polygonsDifference.push(turf.polygon(p[0]));
        }

        // dummy
        let data = [
            { position: [-74.5, 40], size: 10000 },
            { position: [-74.5, 40.5], size: 5000 },
            { position: [-74.6, 40.5], size: 5800 },
            { position: [-74.7, 40.5], size: 100 },
        ];
        this.common.addScatterLayer(data);

        let data2 = [
            { pickup: [-122.42, 37.8], dropoff: [-74.5, 40.5] },
            { pickup: [-122.43, 37.8], dropoff: [-122.42, 37.75] }
        ];
        this.common.addArcLayer(data2);


        const points = await this.common.loadDataLocal('underserved_locations.geojson');
        // console.log(points);
        const colR = hex2RGB(LANDUSE_TYPE_MAPPING.R.color);
        const colB = hex2RGB(LANDUSE_TYPE_MAPPING.B.color);
        const pts = []

        // console.log(points['features'])
        for (let i of points['features']) {
            const p = (i['geometry']['coordinates']);
            const landuse = (i['properties']['landuse']);


            let color = undefined;
            if (landuse === 'R') { color = colR; }
            else if (landuse === 'B') { color = colB; }
            else { color = [0, 128, 0]; }

            pts.push({ position: [p[0], p[1]], size: 15, color: color });
        }

        this.pts = pts
        this.common.addScatterLayer(pts);
        this.points = points;
    }
    public renderCanvas(ctx: CanvasRenderingContext2D) {

        for(let i = 0 ; i < this.areas.length; ++i) {
            this.areas[i].render(ctx);
        }

        for (let i = 0; i < this.pts.length; ++i) {
            const p = this.pts[i];
            ctx.fillStyle = p.color;

            const pp = this.common.toScreen(p.position[0], p.position[1])
            drawingPoint(ctx, pp[0], pp[1]);
        }
    }
}

